import React from 'react';
import { Link } from 'react-router-dom';

const Navbar = () => {
  return (
    <nav className="bg-brown text-cream py-4 px-6 shadow-lg">
      <div className="container mx-auto flex justify-between items-center">
        <Link to="/" className="text-2xl font-bold hover:text-salmon transition-colors">
          Rwandan Art Gallery
        </Link>
        <div className="space-x-6">
          <Link to="/gallery" className="hover:text-salmon transition-colors">Gallery</Link>
          <Link to="/artists" className="hover:text-salmon transition-colors">Artists</Link>
          <Link to="/about" className="hover:text-salmon transition-colors">About</Link>
          <Link to="/login" className="bg-coral px-4 py-2 rounded-lg hover:bg-salmon transition-colors">
            Login
          </Link>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
